import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IEconPoliticalDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionArticle";
import type { IEconPoliticalDiscussionAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionAttachment";
import type { IEconPoliticalDiscussionUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionUser";

export async function test_api_article_attachment_upload_complete_workflow(
  connection: api.IConnection,
) {
  // Step 1: Create a discussion article with economic/political content
  const userId = typia.random<string & tags.Format<"uuid">>();
  const articleTitle = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 5,
    wordMax: 10,
  });
  const articleContent = RandomGenerator.content({
    paragraphs: 2,
    sentenceMin: 8,
    sentenceMax: 15,
    wordMin: 4,
    wordMax: 8,
  });

  const articleData = {
    title: articleTitle,
    content: articleContent,
    category: "Economic Policy",
    econ_political_discussion_user_id: userId,
    status: "published" as const,
  } satisfies IEconPoliticalDiscussionArticle.ICreate;

  const createdArticle =
    await api.functional.econPoliticalDiscussion.articles.create(connection, {
      body: articleData,
    });

  typia.assert(createdArticle);
  TestValidator.equals(
    "article creation successful",
    createdArticle.title,
    articleTitle,
  );
  TestValidator.equals(
    "article content preserved",
    createdArticle.content,
    articleContent,
  );
  TestValidator.equals(
    "article category assigned",
    createdArticle.category,
    "Economic Policy",
  );

  // Step 2: Upload image attachment (JPG format)
  const imageAttachmentData = {
    file_url: "https://example.com/sample-chart.jpg",
    uploader_name: "EconomistUser",
    original_filename: "economic-growth-chart.jpg",
    file_type: "image/jpeg",
    file_size: 2048576, // 2MB
  } satisfies IEconPoliticalDiscussionAttachment.ICreate;

  const imageAttachment =
    await api.functional.econPoliticalDiscussion.articles.attachments.create(
      connection,
      {
        articleId: createdArticle.id,
        body: imageAttachmentData,
      },
    );

  typia.assert(imageAttachment);
  TestValidator.equals(
    "image attachment article reference",
    imageAttachment.article.id,
    createdArticle.id,
  );
  TestValidator.equals(
    "image attachment file type",
    imageAttachment.file_type,
    "image/jpeg",
  );
  TestValidator.equals(
    "image attachment original filename",
    imageAttachment.original_filename,
    "economic-growth-chart.jpg",
  );

  // Step 3: Upload document attachment (PDF format)
  const pdfAttachmentData = {
    file_url: "https://example.com/fed-report.pdf",
    uploader_name: "PolicyAnalyst",
    original_filename: "Federal-Reserve-Report-Q4-2024.pdf",
    file_type: "application/pdf",
    file_size: 5242880, // 5MB
  } satisfies IEconPoliticalDiscussionAttachment.ICreate;

  const pdfAttachment =
    await api.functional.econPoliticalDiscussion.articles.attachments.create(
      connection,
      {
        articleId: createdArticle.id,
        body: pdfAttachmentData,
      },
    );

  typia.assert(pdfAttachment);
  TestValidator.equals(
    "PDF attachment article reference",
    pdfAttachment.article.id,
    createdArticle.id,
  );
  TestValidator.equals(
    "PDF attachment file type",
    pdfAttachment.file_type,
    "application/pdf",
  );
  TestValidator.equals(
    "PDF attachment uploader name",
    pdfAttachment.uploader_name,
    "PolicyAnalyst",
  );

  // Step 4: Upload text document attachment
  const textAttachmentData = {
    file_url: "https://example.com/market-analysis.txt",
    uploader_name: "MarketResearcher",
    original_filename: "Stock-Market-Analysis-2024.txt",
    file_type: "text/plain",
    file_size: 131072, // 128KB
  } satisfies IEconPoliticalDiscussionAttachment.ICreate;

  const textAttachment =
    await api.functional.econPoliticalDiscussion.articles.attachments.create(
      connection,
      {
        articleId: createdArticle.id,
        body: textAttachmentData,
      },
    );

  typia.assert(textAttachment);
  TestValidator.equals(
    "text attachment article reference",
    textAttachment.article.id,
    createdArticle.id,
  );
  TestValidator.equals(
    "text attachment file type",
    textAttachment.file_type,
    "text/plain",
  );
  TestValidator.equals(
    "text attachment file size",
    textAttachment.file_size,
    131072,
  );

  // Step 5: Upload PNG image attachment
  const pngAttachmentData = {
    file_url: "https://example.com/inflation-graph.png",
    uploader_name: "DataVisualizer",
    original_filename: "Inflation-Rate-Graph.png",
    file_type: "image/png",
    file_size: 1572864, // 1.5MB
  } satisfies IEconPoliticalDiscussionAttachment.ICreate;

  const pngAttachment =
    await api.functional.econPoliticalDiscussion.articles.attachments.create(
      connection,
      {
        articleId: createdArticle.id,
        body: pngAttachmentData,
      },
    );

  typia.assert(pngAttachment);
  TestValidator.equals(
    "PNG attachment article reference",
    pngAttachment.article.id,
    createdArticle.id,
  );
  TestValidator.equals(
    "PNG attachment file type",
    pngAttachment.file_type,
    "image/png",
  );
  TestValidator.equals(
    "PNG attachment upload date present",
    pngAttachment.upload_date !== null &&
      pngAttachment.upload_date !== undefined,
    true,
  );

  // Step 6: Validate security scanning and moderation statuses
  const attachments = [
    imageAttachment,
    pdfAttachment,
    textAttachment,
    pngAttachment,
  ];

  for (const attachment of attachments) {
    TestValidator.equals(
      "security scan status present",
      attachment.security_scan_status !== null &&
        attachment.security_scan_status !== undefined,
      true,
    );
    TestValidator.equals(
      "moderation status present",
      attachment.moderation_status !== null &&
        attachment.moderation_status !== undefined,
      true,
    );
    TestValidator.equals(
      "file URL is valid URI",
      attachment.file_url.startsWith("http"),
      true,
    );
    TestValidator.equals(
      "uploader name present",
      attachment.uploader_name.length > 0,
      true,
    );
    TestValidator.equals(
      "file size is positive",
      attachment.file_size > 0,
      true,
    );
    TestValidator.equals(
      "is public flag present",
      attachment.is_public !== null && attachment.is_public !== undefined,
      true,
    );
  }

  // Step 7: Verify all attachments are properly associated with the article
  TestValidator.equals(
    "all attachments reference same article",
    attachments.every((att) => att.article.id === createdArticle.id),
    true,
  );

  // Step 8: Test file type diversity
  const fileTypes = attachments.map((att) => att.file_type);
  TestValidator.equals(
    "mixed file types uploaded",
    fileTypes.includes("image/jpeg") &&
      fileTypes.includes("application/pdf") &&
      fileTypes.includes("text/plain") &&
      fileTypes.includes("image/png"),
    true,
  );

  // Step 9: Validate file size ranges are appropriate
  const fileSizes = attachments.map((att) => att.file_size);
  const totalSize = fileSizes.reduce((sum, size) => sum + size, 0);
  TestValidator.equals(
    "total attachment size reasonable",
    totalSize > 0 && totalSize < 10485760,
    true,
  ); // Under 10MB total

  // Step 10: Confirm upload timestamps are recent and consistent
  const now = new Date();
  const oneHourAgo = new Date(now.getTime() - 60 * 60 * 1000);

  for (const attachment of attachments) {
    const uploadTime = new Date(attachment.upload_date);
    TestValidator.equals(
      "upload timestamp is recent",
      uploadTime >= oneHourAgo && uploadTime <= now,
      true,
    );
  }

  // Final validation: Complete workflow success
  TestValidator.equals(
    "workflow completed successfully",
    attachments.length === 4 &&
      createdArticle.id !== null &&
      createdArticle.id !== undefined,
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconPoliticalDiscussionContentModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionContentModerator";

export async function test_api_content_moderator_password_reset_success(
  connection: api.IConnection,
) {
  // Step 1: Create a content moderator account for testing
  const moderatorEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const moderator: IEconPoliticalDiscussionContentModerator.IAuthorized =
    await api.functional.auth.contentModerator.join.register(connection, {
      body: {
        display_name: RandomGenerator.name(),
        email: moderatorEmail,
        password: "SecurePass123!",
        bio: "Test content moderator for password reset validation",
        avatar_url: "https://example.com/avatar.jpg",
        ip: "192.168.1.100",
        href: "https://example.com/register",
        referrer: "https://example.com/home",
      } satisfies IEconPoliticalDiscussionContentModerator.ICreate,
    });

  // Validate the created moderator account
  typia.assert(moderator);
  TestValidator.equals(
    "moderator account created successfully",
    moderator.id,
    moderator.id,
  );
  TestValidator.equals(
    "moderator email matches input",
    moderator.email,
    moderatorEmail,
  );
  TestValidator.equals(
    "moderator status is active",
    moderator.status,
    "active",
  );

  // Step 2: Request password reset using the moderator's email
  const passwordResetResponse: IEconPoliticalDiscussionContentModerator.IPasswordResetResponse =
    await api.functional.auth.contentModerator.password.reset.resetPassword(
      connection,
      {
        body: {
          email: moderatorEmail,
        } satisfies IEconPoliticalDiscussionContentModerator.IResetPassword,
      },
    );

  // Step 3: Validate the password reset response structure and content
  typia.assert(passwordResetResponse);

  // Validate response contains confirmation message
  TestValidator.predicate(
    "confirmation message should be present",
    passwordResetResponse.message !== null &&
      passwordResetResponse.message !== undefined &&
      passwordResetResponse.message.length > 0,
  );

  // Validate next steps are provided
  TestValidator.predicate(
    "next steps should be provided",
    passwordResetResponse.next_steps !== null &&
      passwordResetResponse.next_steps !== undefined &&
      passwordResetResponse.next_steps.length > 0,
  );

  // Validate email delivery confirmation
  TestValidator.equals(
    "email should be marked as sent",
    passwordResetResponse.email_sent,
    true,
  );

  // Validate the response structure matches expected format
  TestValidator.predicate(
    "message contains expected content",
    passwordResetResponse.message.toLowerCase().includes("reset") ||
      passwordResetResponse.message.toLowerCase().includes("email") ||
      passwordResetResponse.message.toLowerCase().includes("password"),
  );

  TestValidator.predicate(
    "next steps contain email guidance",
    passwordResetResponse.next_steps.toLowerCase().includes("email") ||
      passwordResetResponse.next_steps.toLowerCase().includes("token") ||
      passwordResetResponse.next_steps.toLowerCase().includes("24 hour") ||
      passwordResetResponse.next_steps.toLowerCase().includes("instructions"),
  );

  // Step 4: Verify that password reset works with exact same email (idempotency)
  const secondResetResponse: IEconPoliticalDiscussionContentModerator.IPasswordResetResponse =
    await api.functional.auth.contentModerator.password.reset.resetPassword(
      connection,
      {
        body: {
          email: moderatorEmail,
        } satisfies IEconPoliticalDiscussionContentModerator.IResetPassword,
      },
    );

  typia.assert(secondResetResponse);

  // Validate consistent response for repeated requests
  TestValidator.equals(
    "second reset request also confirms email sent",
    secondResetResponse.email_sent,
    true,
  );
  TestValidator.predicate(
    "second reset has confirmation message",
    secondResetResponse.message !== null &&
      secondResetResponse.message !== undefined,
  );

  // Step 5: Validate response data integrity
  TestValidator.equals(
    "both responses have email sent status",
    passwordResetResponse.email_sent,
    secondResetResponse.email_sent,
  );

  TestValidator.predicate(
    "responses contain similar messaging",
    passwordResetResponse.message.length > 0 &&
      secondResetResponse.message.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconPoliticalDiscussionContentModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionContentModerator";

/**
 * Test password reset request with non-existent email address for content
 * moderators.
 *
 * Validates that appropriate error handling occurs when attempting password
 * reset for accounts that don't exist in the system. Ensures secure response
 * without revealing account existence.
 *
 * This test checks security behavior to prevent account enumeration attacks by
 * ensuring the system handles non-existent email addresses gracefully without
 * leaking information about account existence.
 */
export async function test_api_content_moderator_password_reset_nonexistent_email(
  connection: api.IConnection,
) {
  // Generate a random email address that doesn't exist in the system
  const nonExistentEmail: string = typia.random<
    string & tags.Format<"email">
  >();

  // Attempt password reset with the non-existent email
  const passwordResetRequest = {
    email: nonExistentEmail,
  } satisfies IEconPoliticalDiscussionContentModerator.IResetPassword;

  // Call the password reset endpoint - this should handle non-existent emails gracefully
  const resetResponse =
    await api.functional.auth.contentModerator.password.reset.resetPassword(
      connection,
      {
        body: passwordResetRequest,
      },
    );

  // Validate the response structure and behavior
  typia.assert(resetResponse);

  // Verify the response contains appropriate information about the password reset process
  TestValidator.equals(
    "response contains message",
    resetResponse.message !== undefined && resetResponse.message.length > 0,
    true,
  );
  TestValidator.equals(
    "response contains next_steps",
    resetResponse.next_steps !== undefined &&
      resetResponse.next_steps.length > 0,
    true,
  );
  TestValidator.equals(
    "response contains email_sent status",
    typeof resetResponse.email_sent === "boolean",
    true,
  );

  // The email_sent flag should indicate whether the reset email was actually sent
  // For security reasons, the system may either:
  // 1. Always return true (without actually sending) to avoid revealing account existence
  // 2. Return false if the email doesn't exist (though this can be a security concern)
  // Either behavior is acceptable as long as no sensitive information is leaked

  // Additional validation to ensure no error information is exposed
  TestValidator.predicate(
    "no error details in message",
    !resetResponse.message.toLowerCase().includes("not found") &&
      !resetResponse.message.toLowerCase().includes("does not exist"),
  );
  TestValidator.predicate(
    "no email-specific information leaked",
    !resetResponse.message.includes(nonExistentEmail),
  );
}

