  // Step 6: Upload third attachment and validate
  const thirdAttachment: IEconPoliticalDiscussionAttachment =
    await api.functional.econPoliticalDiscussion.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: attachment3,
      },
