    await api.functional.auth.systemAdministrator.join.create(connection, {
      body: {
        display_name: adminDisplayName,
        email: adminEmail,
        bio: `System administrator for category management testing`,
        status: "active",
      } satisfies IEconPoliticalDiscussionUser.ICreate,
    });
