  );

  // Test with limit 50 (larger page size)
  const largePageResult: IPageIEconPoliticalDiscussionUser.ISummary =
    await api.functional.econPoliticalDiscussion.systemAdministrator.users.index(
      connection,
      {
        body: {
          page: 1,
          limit: 50,
        } satisfies IEconPoliticalDiscussionUser.IRequest,
      },
    );
  typia.assert(largePageResult);
  TestValidator.equals(
    "large page limit should be 50",
    largePageResult.pagination.limit,
    50,
  );
  TestValidator.predicate(
    "large page should have more users",
    largePageResult.data.length >= 10,
  );

  // Step 5: Test forward pagination (page 1, 2, 3)
  const page1Result: IPageIEconPoliticalDiscussionUser.ISummary =
    await api.functional.econPoliticalDiscussion.systemAdministrator.users.index(
      connection,
      {
        body: {
          page: 1,
          limit: 10,
        } satisfies IEconPoliticalDiscussionUser.IRequest,
      },
    );
  typia.assert(page1Result);

  const page2Result: IPageIEconPoliticalDiscussionUser.ISummary =
    await api.functional.econPoliticalDiscussion.systemAdministrator.users.index(
      connection,
      {
        body: {
          page: 2,
          limit: 10,
        } satisfies IEconPoliticalDiscussionUser.IRequest,
      },
    );
  typia.assert(page2Result);
  TestValidator.equals(
    "page 2 should be current page 2",
    page2Result.pagination.current,
    2,
  );
  TestValidator.predicate(
    "page 2 should have different users than page 1",
    page1Result.data.some(
      (user1) => !page2Result.data.some((user2) => user1.id === user2.id),
    ),
  );

  const page3Result: IPageIEconPoliticalDiscussionUser.ISummary =
    await api.functional.econPoliticalDiscussion.systemAdministrator.users.index(
      connection,
      {
        body: {
          page: 3,
          limit: 10,
        } satisfies IEconPoliticalDiscussionUser.IRequest,
      },
    );
  typia.assert(page3Result);
  TestValidator.equals(
    "page 3 should be current page 3",
    page3Result.pagination.current,
    3,
  );

  // Step 6: Test pagination metadata consistency
  TestValidator.equals(
    "total records should be consistent",
    page1Result.pagination.records,
    page2Result.pagination.records,
  );
  TestValidator.equals(
    "total records should be consistent",
    page1Result.pagination.records,
    page3Result.pagination.records,
  );

  // Step 7: Test sorting functionality
  const sortedByName: IPageIEconPoliticalDiscussionUser.ISummary =
    await api.functional.econPoliticalDiscussion.systemAdministrator.users.index(
      connection,
      {
        body: {
          page: 1,
          limit: 10,
          order_by: "display_name",
          order_direction: "asc",
        } satisfies IEconPoliticalDiscussionUser.IRequest,
      },
    );
  typia.assert(sortedByName);
  TestValidator.predicate(
    "users should be sorted by name ascending",
    sortedByName.data.every(
      (user, index, arr) =>
        index === 0 || user.display_name >= arr[index - 1].display_name,
    ),
  );

  // Step 8: Test boundary conditions - non-existent page
  const nonExistentPageResult: IPageIEconPoliticalDiscussionUser.ISummary =
    await api.functional.econPoliticalDiscussion.systemAdministrator.users.index(
      connection,
      {
        body: {
          page: 999,
          limit: 20,
        } satisfies IEconPoliticalDiscussionUser.IRequest,
      },
    );
  typia.assert(nonExistentPageResult);
  TestValidator.equals(
    "non-existent page should return empty data",
    nonExistentPageResult.data.length,
    0,
  );
  TestValidator.equals(
    "non-existent page should maintain pagination info",
    nonExistentPageResult.pagination.current,
    999,
  );

  // Step 9: Test search functionality with pagination
  const searchResult: IPageIEconPoliticalDiscussionUser.ISummary =
    await api.functional.econPoliticalDiscussion.systemAdministrator.users.index(
      connection,
      {
        body: {
          page: 1,
          limit: 10,
          search: "test",
        } satisfies IEconPoliticalDiscussionUser.IRequest,
      },
    );
  typia.assert(searchResult);
  TestValidator.predicate(
    "search should filter users",
    searchResult.data.length <= defaultPageResult.data.length,
  );

  // Step 10: Verify pagination calculations
  if (defaultPageResult.pagination.records > 0) {
    TestValidator.predicate(
      "pages calculation should be correct",
      defaultPageResult.pagination.pages >= 1,
    );
    TestValidator.equals(
      "last page should be correct",
      defaultPageResult.pagination.pages,
      Math.ceil(
        defaultPageResult.pagination.records /
          defaultPageResult.pagination.limit,
      ),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconPoliticalDiscussionSystemAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionSystemAdministrator";
import type { IEconPoliticalDiscussionUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionUser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIEconPoliticalDiscussionUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIEconPoliticalDiscussionUser";

/**
 * Test user search behavior when no users match search criteria.
 *
 * Validates that the system returns appropriate empty results with correct
 * pagination metadata (zero records, zero pages) when search filters return no
 * matches. Tests various filter combinations that should yield empty results,
 * such as searching for non-existent usernames or filtering by status values
 * that don't exist. Ensures administrators receive meaningful feedback when
 * searches don't match any users rather than errors or malformed responses.
 */
export async function test_api_admin_user_search_empty_results(
  connection: api.IConnection,
) {
  // 1. Authenticate as system administrator
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const admin: IEconPoliticalDiscussionSystemAdministrator.IAuthorized =
    await api.functional.auth.systemAdministrator.join.create(connection, {
      body: {
        display_name: RandomGenerator.name(),
        email: adminEmail,
        status: "active",
      } satisfies IEconPoliticalDiscussionUser.ICreate,
    });
  typia.assert(admin);

  // 2. Test search with non-existent display name
  const nonexistentNameSearch =
    await api.functional.econPoliticalDiscussion.systemAdministrator.users.index(
      connection,
      {
        body: {
          search: "ThisUserNameDoesNotExistInTheSystem",
        } satisfies IEconPoliticalDiscussionUser.IRequest,
      },
    );
  typia.assert(nonexistentNameSearch);

  TestValidator.equals(
    "empty search results - no matching names",
    nonexistentNameSearch.data,
    [],
  );
  TestValidator.equals(
    "pagination metadata - zero records",
    nonexistentNameSearch.pagination.records,
    0,
  );
  TestValidator.equals(
    "pagination metadata - zero pages",
    nonexistentNameSearch.pagination.pages,
    0,
  );

  // 3. Test search with invalid status filter
  const invalidStatusSearch =
    await api.functional.econPoliticalDiscussion.systemAdministrator.users.index(
      connection,
      {
        body: {
          status: "nonExistentStatus",
        } satisfies IEconPoliticalDiscussionUser.IRequest,
      },
    );
  typia.assert(invalidStatusSearch);

  TestValidator.equals(
    "empty search results - invalid status",
    invalidStatusSearch.data,
    [],
  );
  TestValidator.equals(
    "pagination metadata - zero records for invalid status",
    invalidStatusSearch.pagination.records,
    0,
  );

  // 4. Test search with impossible combination (non-existent name + invalid status)
  const impossibleCombinationSearch =
    await api.functional.econPoliticalDiscussion.systemAdministrator.users.index(
      connection,
      {
        body: {
          search: "NonExistentUser123",
          status: "invalidStatusValue",
        } satisfies IEconPoliticalDiscussionUser.IRequest,
      },
    );
  typia.assert(impossibleCombinationSearch);

  TestValidator.equals(
    "empty search results - impossible combination",
    impossibleCombinationSearch.data,
    [],
  );
  TestValidator.equals(
    "pagination metadata - zero records for combination",
    impossibleCombinationSearch.pagination.records,
    0,
  );

  // 5. Test search with very specific search term that doesn't match
  const specificNonMatchSearch =
    await api.functional.econPoliticalDiscussion.systemAdministrator.users.index(
      connection,
      {
        body: {
          search: "zzzzzzz_nonexistent_very_specific_term_zzzzzzzz",
        } satisfies IEconPoliticalDiscussionUser.IRequest,
      },
    );
  typia.assert(specificNonMatchSearch);

  TestValidator.equals(
    "empty search results - specific non-matching term",
    specificNonMatchSearch.data,
    [],
  );
  TestValidator.equals(
    "pagination metadata - zero records for specific term",
    specificNonMatchSearch.pagination.records,
    0,
  );

  // 6. Test with pagination on empty results
  const paginatedEmptySearch =
    await api.functional.econPoliticalDiscussion.systemAdministrator.users.index(
      connection,
      {
        body: {
          search: "NoMatchUser",
          page: 5,
          limit: 10,
        } satisfies IEconPoliticalDiscussionUser.IRequest,
      },
    );
  typia.assert(paginatedEmptySearch);

  TestValidator.equals(
    "empty search results - paginated",
    paginatedEmptySearch.data,
    [],
  );
  TestValidator.equals(
    "pagination metadata - correct page number",
    paginatedEmptySearch.pagination.current,
    5,
  );
  TestValidator.equals(
    "pagination metadata - limit preserved",
    paginatedEmptySearch.pagination.limit,
    10,
  );
  TestValidator.equals(
    "pagination metadata - zero records despite pagination",
    paginatedEmptySearch.pagination.records,
    0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconPoliticalDiscussionSystemAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionSystemAdministrator";
import type { IEconPoliticalDiscussionUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionUser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIEconPoliticalDiscussionUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIEconPoliticalDiscussionUser";

export async function test_api_admin_user_search_unauthorized_access(
  connection: api.IConnection,
) {
  // 1. Create a system administrator account (dependency requirement)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IEconPoliticalDiscussionSystemAdministrator.IAuthorized =
    await api.functional.auth.systemAdministrator.join.create(connection, {
      body: {
        display_name: RandomGenerator.name(),
        email: adminEmail,
        status: "active",
      } satisfies IEconPoliticalDiscussionUser.ICreate,
    });
  typia.assert(admin);

  // 2. Test unauthorized access - attempt without proper admin authentication
  // Create an unauthenticated connection (no authorization headers)
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  // Test 1: Attempt to access user search without any authentication
  await TestValidator.httpError(
    "user search should reject unauthenticated requests with 401",
    401,
    async () => {
      await api.functional.econPoliticalDiscussion.systemAdministrator.users.index(
        unauthenticatedConnection,
        {
          body: {
            page: 1,
            limit: 20,
          } satisfies IEconPoliticalDiscussionUser.IRequest,
        },
      );
    },
  );

  // Test 2: Attempt with invalid authentication token
  const invalidConnection: api.IConnection = {
    ...connection,
    headers: {
      Authorization: "Bearer invalid_token_12345",
    },
  };

  await TestValidator.httpError(
    "user search should reject invalid tokens with 401",
    401,
    async () => {
      await api.functional.econPoliticalDiscussion.systemAdministrator.users.index(
        invalidConnection,
        {
          body: {
            page: 1,
            limit: 20,
            search: "test",
          } satisfies IEconPoliticalDiscussionUser.IRequest,
        },
      );
    },
  );

  // Test 3: Create a regular user account and test access
  const regularUserEmail = typia.random<string & tags.Format<"email">>();
  const regularUser = await api.functional.auth.systemAdministrator.join.create(
    unauthenticatedConnection,
    {
      body: {
        display_name: RandomGenerator.name(),
        email: regularUserEmail,
        status: "active",
      } satisfies IEconPoliticalDiscussionUser.ICreate,
    },
  );

  // The regular user join should work (it's a public endpoint)
  // Now test if this regular user can access admin functions
  const regularUserConnection: api.IConnection = {
    ...connection,
    headers: {
      Authorization: regularUser.token.access,
    },
  };

  await TestValidator.httpError(
    "user search should reject regular user access with 403",
    403,
    async () => {
      await api.functional.econPoliticalDiscussion.systemAdministrator.users.index(
        regularUserConnection,
        {
          body: {
            page: 1,
            limit: 20,
          } satisfies IEconPoliticalDiscussionUser.IRequest,
        },
      );
    },
  );

  // 3. Verify authorized access still works properly
  const authorizedUsers =
    await api.functional.econPoliticalDiscussion.systemAdministrator.users.index(
      connection,
      {
        body: {
          page: 1,
          limit: 20,
        } satisfies IEconPoliticalDiscussionUser.IRequest,
      },
    );
  typia.assert(authorizedUsers);

  TestValidator.equals(
    "authorized admin access returns user list",
    authorizedUsers.data.length,
    2,
  );

  TestValidator.equals(
    "response contains pagination info",
    authorizedUsers.pagination.current,
    1,
  );

  // Test with search parameters
  const filteredUsers =
    await api.functional.econPoliticalDiscussion.systemAdministrator.users.index(
      connection,
      {
        body: {
          page: 1,
          limit: 10,
          search: admin.display_name,
        } satisfies IEconPoliticalDiscussionUser.IRequest,
      },
    );
  typia.assert(filteredUsers);

  TestValidator.predicate(
    "search results should be filtered correctly",
    filteredUsers.data.some((user) =>
      user.display_name.includes(admin.display_name),
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconPoliticalDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionArticle";
import type { IEconPoliticalDiscussionAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionAttachment";
import type { IEconPoliticalDiscussionRegisteredMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionRegisteredMember";
import type { IEconPoliticalDiscussionUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionUser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIEconPoliticalDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIEconPoliticalDiscussionArticle";

/**
 * Test retrieving a filtered and paginated list of discussion articles written
 * by a specific registered user.
 *
 * Simulates a scenario where a user wants to view their own article history or
 * a moderator wants to review a user's contributions. Validates pagination
 * parameters (page, limit), text search across titles and content, category
 * filtering (Economic Policy, Political Analysis, Market Discussion), status
 * filtering (published, draft), author filtering, sorting options (created_at,
 * updated_at, title, category), and attachment filtering. Ensures the response
 * includes proper pagination metadata and article summaries with all expected
 * fields.
 */
export async function test_api_user_articles_pagination_and_filtering(
  connection: api.IConnection,
) {
  // Step 1: Register a test user to create articles
  const userEmail: string = typia.random<string & tags.Format<"email">>();
  const user: IEconPoliticalDiscussionRegisteredMember.IAuthorized =
    await api.functional.auth.registeredMember.join(connection, {
      body: {
        display_name: RandomGenerator.name(),
        email: userEmail,
        bio: "Economics enthusiast interested in policy analysis",
        status: "active",
      } satisfies IEconPoliticalDiscussionRegisteredMember.ICreate,
    });
  typia.assert(user);

  // Step 2: Create multiple test articles with different categories, statuses, and content
  const categories = [
    "Economic Policy",
    "Political Analysis",
    "Market Discussion",
    "Regulatory Updates",
  ] as const;
  const statuses = ["published", "draft"] as const;

  const articles: IEconPoliticalDiscussionArticle[] = [];

  // Create 10 articles with varied content for comprehensive testing
  for (let i = 0; i < 10; i++) {
    const category = RandomGenerator.pick(categories);
    const status = RandomGenerator.pick(statuses);
    const title = `${category} Discussion #${i + 1}`;
    const content = RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 5,
      sentenceMax: 10,
      wordMin: 4,
      wordMax: 8,
    });

    const article: IEconPoliticalDiscussionArticle =
      await api.functional.econPoliticalDiscussion.registeredMember.articles.create(
        connection,
        {
          body: {
            title,
            content,
            category,
            status,
            econ_political_discussion_user_id: user.id,
            attachments:
              i % 3 === 0
                ? [
                    {
                      file_url: `https://example.com/attachment-${i}.pdf`,
                      uploader_name: user.display_name,
                      original_filename: `document-${i}.pdf`,
                      file_type: "application/pdf",
                      file_size: 1024 * (i + 1),
                    },
                  ]
                : undefined,
          } satisfies IEconPoliticalDiscussionArticle.ICreate,
        },
      );
    typia.assert(article);
    articles.push(article);
  }

  // Step 3: Add some attachments to specific articles for has_attachments filter testing
  for (let i = 0; i < 3; i++) {
    await api.functional.econPoliticalDiscussion.articles.attachments.create(
      connection,
      {
        articleId: articles[i].id,
        body: {
          file_url: `https://example.com/additional-attachment-${i}.jpg`,
          uploader_name: user.display_name,
          original_filename: `chart-${i}.jpg`,
          file_type: "image/jpeg",
          file_size: 2048 * (i + 1),
        } satisfies IEconPoliticalDiscussionAttachment.ICreate,
      },
    );
  }

  // Step 4: Test basic pagination without filters
  const firstPage: IPageIEconPoliticalDiscussionArticle.ISummary =
    await api.functional.econPoliticalDiscussion.registeredMember.users.articles.index(
      connection,
      {
        userId: user.id,
        body: {
          page: 1,
          limit: 5,
        } satisfies IEconPoliticalDiscussionArticle.IRequest,
      },
    );
  typia.assert(firstPage);

  TestValidator.equals(
    "first page should return 5 articles",
    firstPage.data.length,
    5,
  );
  TestValidator.equals(
    "first page should be page 1",
    firstPage.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination limit should be 5",
    firstPage.pagination.limit,
    5,
  );

  // Step 5: Test second page pagination
  const secondPage: IPageIEconPoliticalDiscussionArticle.ISummary =
    await api.functional.econPoliticalDiscussion.registeredMember.users.articles.index(
      connection,
      {
        userId: user.id,
        body: {
          page: 2,
          limit: 5,
        } satisfies IEconPoliticalDiscussionArticle.IRequest,
      },
    );
  typia.assert(secondPage);

  TestValidator.equals(
    "second page should return remaining articles",
    secondPage.data.length,
    5,
  );
  TestValidator.equals(
    "second page should be page 2",
    secondPage.pagination.current,
    2,
  );

  // Step 6: Test text search functionality
  const searchTerm = "Discussion"; // Should match all article titles
  const searchResults: IPageIEconPoliticalDiscussionArticle.ISummary =
    await api.functional.econPoliticalDiscussion.registeredMember.users.articles.index(
      connection,
      {
        userId: user.id,
        body: {
          search: searchTerm,
          limit: 20,
        } satisfies IEconPoliticalDiscussionArticle.IRequest,
      },
    );
  typia.assert(searchResults);

  TestValidator.equals(
    "search should return all articles with 'Discussion'",
    searchResults.data.length,
    10,
  );
  searchResults.data.forEach((article) => {
    TestValidator.predicate(
      "article title should contain search term",
      article.title.includes(searchTerm) ||
        articles
          .find((a) => a.id === article.id)
          ?.content.includes(searchTerm) ||
        false,
    );
  });

  // Step 7: Test category filtering
  const selectedCategory = "Economic Policy";
  const categoryFiltered: IPageIEconPoliticalDiscussionArticle.ISummary =
    await api.functional.econPoliticalDiscussion.registeredMember.users.articles.index(
      connection,
      {
        userId: user.id,
        body: {
          category: selectedCategory,
          limit: 20,
        } satisfies IEconPoliticalDiscussionArticle.IRequest,
      },
    );
  typia.assert(categoryFiltered);

  categoryFiltered.data.forEach((article) => {
    TestValidator.equals(
      "filtered article should match category",
      article.category,
      selectedCategory,
    );
  });

  // Step 8: Test status filtering
  const selectedStatus = "published";
  const statusFiltered: IPageIEconPoliticalDiscussionArticle.ISummary =
    await api.functional.econPoliticalDiscussion.registeredMember.users.articles.index(
      connection,
      {
        userId: user.id,
        body: {
          status: selectedStatus,
          limit: 20,
        } satisfies IEconPoliticalDiscussionArticle.IRequest,
      },
    );
  typia.assert(statusFiltered);

  statusFiltered.data.forEach((article) => {
    TestValidator.equals(
      "filtered article should match status",
      article.status,
      selectedStatus,
    );
  });

  // Step 9: Test sorting by creation date (descending)
  const sortedByDate: IPageIEconPoliticalDiscussionArticle.ISummary =
    await api.functional.econPoliticalDiscussion.registeredMember.users.articles.index(
      connection,
      {
        userId: user.id,
        body: {
          order_by: "created_at",
          order_direction: "desc",
          limit: 10,
        } satisfies IEconPoliticalDiscussionArticle.IRequest,
      },
    );
  typia.assert(sortedByDate);

  // Verify descending order by created_at
  for (let i = 0; i < sortedByDate.data.length - 1; i++) {
    const currentDate = new Date(sortedByDate.data[i].created_at);
    const nextDate = new Date(sortedByDate.data[i + 1].created_at);
    TestValidator.predicate(
      "articles should be sorted by creation date descending",
      currentDate >= nextDate,
    );
  }

  // Step 10: Test sorting by title (ascending)
  const sortedByTitle: IPageIEconPoliticalDiscussionArticle.ISummary =
    await api.functional.econPoliticalDiscussion.registeredMember.users.articles.index(
      connection,
      {
        userId: user.id,
        body: {
          order_by: "title",
          order_direction: "asc",
          limit: 10,
        } satisfies IEconPoliticalDiscussionArticle.IRequest,
      },
    );
  typia.assert(sortedByTitle);

  // Verify ascending order by title
  for (let i = 0; i < sortedByTitle.data.length - 1; i++) {
    TestValidator.predicate(
      "articles should be sorted by title ascending",
      sortedByTitle.data[i].title <= sortedByTitle.data[i + 1].title,
    );
  }

  // Step 11: Test combined filtering (category + status)
  const combinedFiltered: IPageIEconPoliticalDiscussionArticle.ISummary =
    await api.functional.econPoliticalDiscussion.registeredMember.users.articles.index(
      connection,
      {
        userId: user.id,
        body: {
          category: "Political Analysis",
          status: "draft",
          limit: 20,
        } satisfies IEconPoliticalDiscussionArticle.IRequest,
      },
    );
  typia.assert(combinedFiltered);

  combinedFiltered.data.forEach((article) => {
    TestValidator.equals(
      "filtered article should match category",
      article.category,
      "Political Analysis",
    );
    TestValidator.equals(
      "filtered article should match status",
      article.status,
      "draft",
    );
  });

  // Step 12: Test has_attachments filter
  const withAttachments: IPageIEconPoliticalDiscussionArticle.ISummary =
    await api.functional.econPoliticalDiscussion.registeredMember.users.articles.index(
      connection,
      {
        userId: user.id,
        body: {
          has_attachments: true,
          limit: 20,
        } satisfies IEconPoliticalDiscussionArticle.IRequest,
      },
    );
  typia.assert(withAttachments);

  // Verify that returned articles have attachments (by checking our created test data)
  TestValidator.predicate(
    "should return articles with attachments",
    withAttachments.data.length > 0,
  );

  // Step 13: Test pagination metadata accuracy
  const fullList: IPageIEconPoliticalDiscussionArticle.ISummary =
    await api.functional.econPoliticalDiscussion.registeredMember.users.articles.index(
      connection,
      {
        userId: user.id,
        body: {
          limit: 20,
        } satisfies IEconPoliticalDiscussionArticle.IRequest,
      },
    );
  typia.assert(fullList);

  TestValidator.equals(
    "pagination should show correct total records",
    fullList.pagination.records,
    10,
  );
  TestValidator.equals(
    "pagination should calculate correct total pages",
    fullList.pagination.pages,
    1,
  );
