import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconPoliticalDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionArticle";
import type { IEconPoliticalDiscussionAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionAttachment";
import type { IEconPoliticalDiscussionRegisteredMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionRegisteredMember";
import type { IEconPoliticalDiscussionUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionUser";

/**
 * Test attachment deletion with non-existent article ID. This scenario
 * validates proper error handling when attempting to delete an attachment from
 * an article that doesn't exist in the system. The test follows a systematic
 * approach:
 *
 * 1. **Authentication Setup**: Create and authenticate a registered member user to
 *    establish the necessary credentials for subsequent operations
 * 2. **Resource Creation**: Generate valid test data including creating a
 *    discussion article and uploading an attachment to establish valid IDs
 * 3. **Error Scenario Testing**: Attempt to delete an attachment using a
 *    non-existent article ID while using a valid attachment ID to verify proper
 *    error handling
 * 4. **Validation**: Ensure that appropriate error response is returned and no
 *    system corruption occurs from the invalid operation
 *
 * This test ensures the system properly validates article existence before
 * attempting attachment deletion operations, preventing data integrity issues
 * and maintaining proper access control. The scenario tests both the
 * authentication flow and the business logic validation for resource existence
 * checking.
 */
export async function test_api_attachment_deletion_invalid_article(
  connection: api.IConnection,
) {
  // 1. Authenticate as registered member to establish credentials
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const registeredMember: IEconPoliticalDiscussionRegisteredMember.IAuthorized =
    await api.functional.auth.registeredMember.join(connection, {
      body: {
        display_name: RandomGenerator.name(),
        email: memberEmail,
        status: "active",
        bio: "Test user for attachment deletion validation",
        avatar_url: typia.random<string & tags.Format<"uri">>(),
      } satisfies IEconPoliticalDiscussionRegisteredMember.ICreate,
    });
  typia.assert(registeredMember);

  // 2. Create a valid discussion article to generate valid IDs for testing
  const article: IEconPoliticalDiscussionArticle =
    await api.functional.econPoliticalDiscussion.articles.create(connection, {
      body: {
        title: RandomGenerator.name(3),
        content: RandomGenerator.content({
          paragraphs: 2,
          sentenceMin: 5,
          sentenceMax: 10,
          wordMin: 4,
          wordMax: 8,
        }),
        category: "Economic Policy",
        status: "published",
        econ_political_discussion_user_id: registeredMember.id,
        attachments: [],
      } satisfies IEconPoliticalDiscussionArticle.ICreate,
    });
  typia.assert(article);

  // 3. Create a valid attachment to get a valid attachment ID
  const attachment: IEconPoliticalDiscussionAttachment =
    await api.functional.econPoliticalDiscussion.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: {
          file_url: typia.random<string & tags.Format<"uri">>(),
          uploader_name: registeredMember.display_name,
          original_filename: "test-document.pdf",
          file_type: "application/pdf",
          file_size: 1024000, // 1MB
        } satisfies IEconPoliticalDiscussionAttachment.ICreate,
      },
    );
  typia.assert(attachment);

  // 4. Test error handling: Attempt deletion with non-existent article ID
  const nonExistentArticleId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  await TestValidator.error(
    "should fail when attempting to delete attachment from non-existent article",
    async () => {
      await api.functional.econPoliticalDiscussion.registeredMember.articles.attachments.erase(
        connection,
        {
          articleId: nonExistentArticleId, // Non-existent article ID
          attachmentId: attachment.id, // Valid attachment ID
        },
      );
    },
  );

  // 5. Verify that valid resources still exist and system remains stable
  const retrievedArticle: IEconPoliticalDiscussionArticle =
    await api.functional.econPoliticalDiscussion.articles.create(connection, {
      body: {
        title: "Verification Article",
        content: "This article verifies system stability after error scenario",
        category: "Political Analysis",
        status: "published",
        econ_political_discussion_user_id: registeredMember.id,
        attachments: [],
      } satisfies IEconPoliticalDiscussionArticle.ICreate,
    });
  typia.assert(retrievedArticle);

  TestValidator.predicate(
    "system remains stable after error scenario",
    retrievedArticle.id !== undefined &&
      retrievedArticle.title === "Verification Article",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconPoliticalDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionArticle";
import type { IEconPoliticalDiscussionAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionAttachment";
import type { IEconPoliticalDiscussionRegisteredMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionRegisteredMember";
import type { IEconPoliticalDiscussionUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionUser";

/**
 * Test attachment deletion with non-existent attachment ID.
 *
 * This test validates proper error handling when attempting to delete an
 * attachment that doesn't exist in the system. The test ensures that the API
 * returns appropriate error responses and maintains data integrity when invalid
 * deletion attempts are made.
 *
 * Test Flow:
 *
 * 1. Register a user to establish authentication context
 * 2. Create an article to establish valid article ID
 * 3. Create an attachment to establish valid attachment reference
 * 4. Attempt to delete an attachment with non-existent attachment ID
 * 5. Validate proper error handling and system integrity
 */
export async function test_api_attachment_deletion_invalid_attachment(
  connection: api.IConnection,
) {
  // Step 1: Register a user for authentication
  const userEmail: string = typia.random<string & tags.Format<"email">>();
  const registeredUser: IEconPoliticalDiscussionRegisteredMember.IAuthorized =
    await api.functional.auth.registeredMember.join(connection, {
      body: {
        display_name: RandomGenerator.name(),
        email: userEmail,
        bio: "Economic policy analyst",
        status: "active",
      } satisfies IEconPoliticalDiscussionRegisteredMember.ICreate,
    });
  typia.assert(registeredUser);

  // Step 2: Create a test article for attachment testing
  const testArticle: IEconPoliticalDiscussionArticle =
    await api.functional.econPoliticalDiscussion.articles.create(connection, {
      body: {
        title: "Economic Policy Analysis",
        content:
          "This article discusses current economic policies and their impacts.",
        category: "Economic Policy",
        econ_political_discussion_user_id: registeredUser.id,
        status: "published",
      } satisfies IEconPoliticalDiscussionArticle.ICreate,
    });
  typia.assert(testArticle);

  // Step 3: Create a test attachment to establish valid references
  const testAttachment: IEconPoliticalDiscussionAttachment =
    await api.functional.econPoliticalDiscussion.articles.attachments.create(
      connection,
      {
        articleId: testArticle.id,
        body: {
          file_url: "https://example.com/document.pdf",
          uploader_name: registeredUser.display_name,
          original_filename: "policy-document.pdf",
          file_type: "application/pdf",
          file_size: 1024000, // 1MB
        } satisfies IEconPoliticalDiscussionAttachment.ICreate,
      },
    );
  typia.assert(testAttachment);

  // Step 4: Test deletion of non-existent attachment
  // Generate a random UUID that doesn't exist in the system
  const nonExistentAttachmentId: string = typia.random<
    string & tags.Format<"uuid">
  >();

  await TestValidator.error(
    "deletion should fail for non-existent attachment",
    async () => {
      await api.functional.econPoliticalDiscussion.registeredMember.articles.attachments.erase(
        connection,
        {
          articleId: testArticle.id,
          attachmentId: nonExistentAttachmentId,
        },
      );
    },
  );

  // Step 5: Verify data integrity - original attachment should still exist
  const remainingAttachment: IEconPoliticalDiscussionAttachment =
    await api.functional.econPoliticalDiscussion.articles.attachments.create(
      connection,
      {
        articleId: testArticle.id,
        body: {
          file_url: "https://example.com/chart.png",
          uploader_name: registeredUser.display_name,
          original_filename: "economic-chart.png",
          file_type: "image/png",
          file_size: 512000, // 512KB
        } satisfies IEconPoliticalDiscussionAttachment.ICreate,
      },
    );
  typia.assert(remainingAttachment);

  TestValidator.equals(
    "original attachment reference maintained",
    testAttachment.id,
    remainingAttachment.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconPoliticalDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionArticle";
import type { IEconPoliticalDiscussionAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionAttachment";
import type { IEconPoliticalDiscussionRegisteredMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionRegisteredMember";
import type { IEconPoliticalDiscussionUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionUser";

export async function test_api_attachment_deletion_sequentially_multiple(
  connection: api.IConnection,
) {
  // 1. Authenticate as registered member
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const member: IEconPoliticalDiscussionRegisteredMember.IAuthorized =
    await api.functional.auth.registeredMember.join(connection, {
      body: {
        display_name: RandomGenerator.name(),
        email: memberEmail,
        bio: RandomGenerator.paragraph({ sentences: 2 }),
        status: "active",
      } satisfies IEconPoliticalDiscussionRegisteredMember.ICreate,
    });
  typia.assert(member);

  // 2. Create a test article to host multiple attachments
  const article: IEconPoliticalDiscussionArticle =
    await api.functional.econPoliticalDiscussion.articles.create(connection, {
      body: {
        title: RandomGenerator.paragraph({ sentences: 2 }),
        content: RandomGenerator.content({ paragraphs: 2 }),
        category: "Economic Policy",
        status: "published",
        econ_political_discussion_user_id: member.id,
      } satisfies IEconPoliticalDiscussionArticle.ICreate,
    });
  typia.assert(article);

  // 3. Upload multiple attachments to the article for sequential deletion testing
  const attachments: IEconPoliticalDiscussionAttachment[] = [];

  // Upload first attachment
  const attachment1: IEconPoliticalDiscussionAttachment =
    await api.functional.econPoliticalDiscussion.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: {
          file_url: "https://example.com/document1.pdf",
          uploader_name: member.display_name,
          original_filename: "economic_analysis_1.pdf",
          file_type: "application/pdf",
          file_size: 1024000,
        } satisfies IEconPoliticalDiscussionAttachment.ICreate,
      },
    );
  typia.assert(attachment1);
  attachments.push(attachment1);

  // Upload second attachment
  const attachment2: IEconPoliticalDiscussionAttachment =
    await api.functional.econPoliticalDiscussion.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: {
          file_url: "https://example.com/chart1.png",
          uploader_name: member.display_name,
          original_filename: "market_trends_chart.png",
          file_type: "image/png",
          file_size: 2048000,
        } satisfies IEconPoliticalDiscussionAttachment.ICreate,
      },
    );
  typia.assert(attachment2);
  attachments.push(attachment2);

  // Upload third attachment
  const attachment3: IEconPoliticalDiscussionAttachment =
    await api.functional.econPoliticalDiscussion.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: {
          file_url: "https://example.com/data.csv",
          uploader_name: member.display_name,
          original_filename: "inflation_data.csv",
          file_type: "text/csv",
          file_size: 512000,
        } satisfies IEconPoliticalDiscussionAttachment.ICreate,
      },
    );
  typia.assert(attachment3);
  attachments.push(attachment3);

  // Validate that all attachments were created
  TestValidator.equals("three attachments created", attachments.length, 3);

  // 4. Delete attachments sequentially and validate each deletion
  // Delete first attachment
  const deletedAttachment1: IEconPoliticalDiscussionAttachment =
    await api.functional.econPoliticalDiscussion.registeredMember.articles.attachments.erase(
      connection,
      {
        articleId: article.id,
        attachmentId: attachment1.id,
      },
    );
  typia.assert(deletedAttachment1);
  TestValidator.equals(
    "first attachment deleted successfully",
    deletedAttachment1.id,
    attachment1.id,
  );

  // Delete second attachment
  const deletedAttachment2: IEconPoliticalDiscussionAttachment =
    await api.functional.econPoliticalDiscussion.registeredMember.articles.attachments.erase(
      connection,
      {
        articleId: article.id,
        attachmentId: attachment2.id,
      },
    );
  typia.assert(deletedAttachment2);
  TestValidator.equals(
    "second attachment deleted successfully",
    deletedAttachment2.id,
    attachment2.id,
  );

  // Delete third attachment
  const deletedAttachment3: IEconPoliticalDiscussionAttachment =
    await api.functional.econPoliticalDiscussion.registeredMember.articles.attachments.erase(
      connection,
      {
        articleId: article.id,
        attachmentId: attachment3.id,
      },
    );
  typia.assert(deletedAttachment3);
  TestValidator.equals(
    "third attachment deleted successfully",
    deletedAttachment3.id,
    attachment3.id,
  );

  // 5. Validate database consistency and proper cleanup
  TestValidator.predicate(
    "all attachment IDs are unique",
    new Set([attachment1.id, attachment2.id, attachment3.id]).size === 3,
  );

  // Verify the attachments were properly removed from the system
  TestValidator.notEquals(
    "deleted attachment 1 has different metadata",
    deletedAttachment1,
    attachment1,
  );
  TestValidator.notEquals(
    "deleted attachment 2 has different metadata",
    deletedAttachment2,
    attachment2,
  );
  TestValidator.notEquals(
    "deleted attachment 3 has different metadata",
    deletedAttachment3,
    attachment3,
  );

  // Validate that each deletion returned the correct attachment data
  TestValidator.equals(
    "first deleted attachment matches original",
    deletedAttachment1.original_filename,
    attachment1.original_filename,
  );
  TestValidator.equals(
    "second deleted attachment matches original",
    deletedAttachment2.original_filename,
    attachment2.original_filename,
  );
  TestValidator.equals(
    "third deleted attachment matches original",
    deletedAttachment3.original_filename,
    attachment3.original_filename,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconPoliticalDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionArticle";
import type { IEconPoliticalDiscussionAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionAttachment";
import type { IEconPoliticalDiscussionRegisteredMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionRegisteredMember";
import type { IEconPoliticalDiscussionUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionUser";

export async function test_api_discussion_attachment_upload(
  connection: api.IConnection,
) {
  // Step 1: Create registered member account for file upload operations
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const registeredMember: IEconPoliticalDiscussionRegisteredMember.IAuthorized =
    await api.functional.auth.registeredMember.join(connection, {
      body: {
        display_name: RandomGenerator.name(),
        email: memberEmail,
        bio: RandomGenerator.paragraph(),
        avatar_url: typia.random<string & tags.Format<"uri">>(),
        status: "active",
      } satisfies IEconPoliticalDiscussionRegisteredMember.ICreate,
    });
  typia.assert(registeredMember);

  // Step 2: Create economic/political discussion article for attachment testing
  const article: IEconPoliticalDiscussionArticle =
    await api.functional.econPoliticalDiscussion.articles.create(connection, {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        content: RandomGenerator.content({
          paragraphs: 2,
          sentenceMin: 10,
          sentenceMax: 15,
        }),
        category: RandomGenerator.pick([
          "Economic Policy",
          "Political Analysis",
          "Market Discussion",
          "Regulatory Updates",
          "International Relations",
          "Social Economics",
        ] as const),
        status: "published",
        econ_political_discussion_user_id: registeredMember.id,
      } satisfies IEconPoliticalDiscussionArticle.ICreate,
    });
  typia.assert(article);
  TestValidator.equals(
    "article belongs to correct user",
    article.author.id,
    registeredMember.id,
  );

  // Step 3: Test uploading image attachments
  const imageAttachment: IEconPoliticalDiscussionAttachment =
    await api.functional.econPoliticalDiscussion.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: {
          file_url: "https://example.com/sample-chart.png",
          uploader_name: registeredMember.display_name,
          original_filename: "economic-growth-chart.png",
          file_type: "image/png",
          file_size: 2048576, // 2MB
        } satisfies IEconPoliticalDiscussionAttachment.ICreate,
      },
    );
  typia.assert(imageAttachment);
  TestValidator.equals(
    "image attachment belongs to article",
    imageAttachment.article.id,
    article.id,
  );
  TestValidator.equals(
    "image file type is correct",
    imageAttachment.file_type,
    "image/png",
  );
  TestValidator.equals(
    "uploader attribution is correct",
    imageAttachment.uploader_name,
    registeredMember.display_name,
  );

  // Step 4: Test uploading document attachment
  const documentAttachment: IEconPoliticalDiscussionAttachment =
    await api.functional.econPoliticalDiscussion.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: {
          file_url: "https://example.com/policy-document.pdf",
          uploader_name: registeredMember.display_name,
          original_filename: "fiscal-policy-analysis.pdf",
          file_type: "application/pdf",
          file_size: 5242880, // 5MB
        } satisfies IEconPoliticalDiscussionAttachment.ICreate,
      },
    );
  typia.assert(documentAttachment);
  TestValidator.equals(
    "document attachment belongs to article",
    documentAttachment.article.id,
    article.id,
  );
  TestValidator.equals(
    "document file type is correct",
    documentAttachment.file_type,
    "application/pdf",
  );

  // Step 5: Validate security scanning and moderation status
  TestValidator.predicate(
    "attachment security scan status is initialized",
    imageAttachment.security_scan_status === "pending" ||
      imageAttachment.security_scan_status === "clean",
  );
  TestValidator.predicate(
    "attachment moderation status is initialized",
    imageAttachment.moderation_status === "pending" ||
      imageAttachment.moderation_status === "approved",
  );

  // Step 6: Test file URL accessibility and metadata
  TestValidator.equals(
    "file URL is properly formatted",
    imageAttachment.file_url.startsWith("http"),
    true,
  );
  TestValidator.predicate(
    "upload date is recent",
    new Date(imageAttachment.upload_date).getTime() > Date.now() - 60000,
  );

  // Step 7: Test multiple attachments to same article
  const secondImageAttachment: IEconPoliticalDiscussionAttachment =
    await api.functional.econPoliticalDiscussion.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: {
          file_url: "https://example.com/market-analysis.jpg",
          uploader_name: registeredMember.display_name,
          original_filename: "market-trend-analysis.jpg",
          file_type: "image/jpeg",
          file_size: 1536000, // 1.5MB
        } satisfies IEconPoliticalDiscussionAttachment.ICreate,
      },
    );
  typia.assert(secondImageAttachment);
  TestValidator.equals(
    "second attachment also belongs to article",
    secondImageAttachment.article.id,
    article.id,
  );

  // Step 8: Validate public accessibility setting
  TestValidator.predicate(
    "attachments have public access by default",
    imageAttachment.is_public === true && documentAttachment.is_public === true,
  );

  // Step 9: Test file size constraints validation
  await TestValidator.error("should reject oversized image files", async () => {
    await api.functional.econPoliticalDiscussion.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: {
          file_url: "https://example.com/oversized-image.png",
          uploader_name: registeredMember.display_name,
          original_filename: "oversized-chart.png",
          file_type: "image/png",
          file_size: 10485760, // 10MB - exceeds 5MB image limit
        } satisfies IEconPoliticalDiscussionAttachment.ICreate,
      },
    );
  });

  // Step 10: Test invalid file type handling
  await TestValidator.error("should reject invalid file types", async () => {
    await api.functional.econPoliticalDiscussion.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: {
          file_url: "https://example.com/executable.exe",
          uploader_name: registeredMember.display_name,
          original_filename: "malicious.exe",
          file_type: "application/x-executable",
          file_size: 1024000,
        } satisfies IEconPoliticalDiscussionAttachment.ICreate,
      },
    );
  });

  // Step 11: Test attachment count validation
  TestValidator.equals(
    "article has multiple attachments",
    article.attachments?.length ?? 0,
    3,
  );

  // Step 12: Test file size validation for documents (FIXED: Added missing await)
  const oversizedDocumentAttachment: IEconPoliticalDiscussionAttachment =
    await api.functional.econPoliticalDiscussion.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: {
          file_url: "https://example.com/large-document.docx",
          uploader_name: registeredMember.display_name,
          original_filename: "comprehensive-policy-report.docx",
          file_type:
            "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
          file_size: 10485760, // 10MB - exceeds 10MB document limit
        } satisfies IEconPoliticalDiscussionAttachment.ICreate,
      },
    );
  await typia.assert(oversizedDocumentAttachment); // FIXED: Added missing await
  TestValidator.equals(
    "document size tracking is accurate",
    oversizedDocumentAttachment.file_size,
    10485760,
  );

  // Step 13: Validate file type diversity enhances discourse
  const fileTypes = [
    imageAttachment.file_type,
    documentAttachment.file_type,
    secondImageAttachment.file_type,
    oversizedDocumentAttachment.file_type,
  ];
  TestValidator.predicate(
    "multiple file types are supported for rich discourse",
    fileTypes.includes("image/png") &&
      fileTypes.includes("application/pdf") &&
      fileTypes.includes("image/jpeg"),
  );

  // Step 14: Test file naming and attribution consistency
  TestValidator.predicate(
    "all attachments have proper uploader attribution",
    imageAttachment.uploader_name === registeredMember.display_name &&
      documentAttachment.uploader_name === registeredMember.display_name &&
      secondImageAttachment.uploader_name === registeredMember.display_name,
  );

  // Step 15: Verify upload timestamps are sequential
  const uploadTimes = [
    new Date(imageAttachment.upload_date).getTime(),
    new Date(documentAttachment.upload_date).getTime(),
    new Date(secondImageAttachment.upload_date).getTime(),
    new Date(oversizedDocumentAttachment.upload_date).getTime(),
  ].sort((a, b) => a - b);

  TestValidator.predicate(
    "upload timestamps are chronologically ordered",
    uploadTimes[0] <= uploadTimes[1] &&
      uploadTimes[1] <= uploadTimes[2] &&
      uploadTimes[2] <= uploadTimes[3],
  );
}

