import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconPoliticalDiscussionGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionGuestUser";

/**
 * Validate successful token refresh operation for authenticated guest users.
 *
 * This test ensures guest users can extend their session without
 * re-authentication by providing valid refresh tokens. The test validates that
 * new access and refresh tokens are generated properly while maintaining user
 * session integrity.
 *
 * Test flow:
 *
 * 1. Create guest user account with join endpoint to obtain initial tokens
 * 2. Call token refresh endpoint to extend session without re-authentication
 * 3. Validate response contains updated user profile and new token pair
 * 4. Verify token refresh maintains authenticated user context
 */
export async function test_api_guest_user_token_refresh_success(
  connection: api.IConnection,
) {
  // Step 1: Create guest user account to obtain initial refresh token
  const guestUser: IEconPoliticalDiscussionGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: {
        display_name: RandomGenerator.name(),
        email: typia.random<string & tags.Format<"email">>(),
        bio: RandomGenerator.paragraph({ sentences: 2 }),
        avatar_url: typia.random<string & tags.Format<"uri">>(),
      } satisfies IEconPoliticalDiscussionGuestUser.ICreate,
    });
  typia.assert(guestUser);

  // Validate initial user creation and token structure
  TestValidator.equals(
    "guest user account created successfully",
    guestUser.status,
    "active",
  );
  TestValidator.equals(
    "initial access token provided",
    !!guestUser.token.access,
    true,
  );
  TestValidator.equals(
    "initial refresh token provided",
    !!guestUser.token.refresh,
    true,
  );
  TestValidator.equals(
    "access token has expiration",
    !!guestUser.token.expired_at,
    true,
  );
  TestValidator.equals(
    "refresh token has expiration",
    !!guestUser.token.refreshable_until,
    true,
  );

  // Step 2: Test token refresh operation using the refresh token
  const refreshedUser: IEconPoliticalDiscussionGuestUser.IAuthorized =
    await api.functional.auth.guestUser.refresh.refreshToken(connection);
  typia.assert(refreshedUser);

  // Step 3: Validate token refresh response and user session integrity
  TestValidator.equals(
    "user profile preserved after refresh",
    refreshedUser.id,
    guestUser.id,
  );
  TestValidator.equals(
    "user display name preserved",
    refreshedUser.display_name,
    guestUser.display_name,
  );
  TestValidator.equals(
    "user email preserved",
    refreshedUser.email,
    guestUser.email,
  );
  TestValidator.equals(
    "user status remains active",
    refreshedUser.status,
    "active",
  );

  // Step 4: Validate new token pair generation
  TestValidator.equals(
    "new access token generated",
    !!refreshedUser.token.access,
    true,
  );
  TestValidator.equals(
    "new refresh token generated",
    !!refreshedUser.token.refresh,
    true,
  );
  TestValidator.equals(
    "access token expiration updated",
    !!refreshedUser.token.expired_at,
    true,
  );
  TestValidator.equals(
    "refresh token expiration updated",
    !!refreshedUser.token.refreshable_until,
    true,
  );

  // Step 5: Ensure tokens are different (indicating successful refresh)
  TestValidator.notEquals(
    "access token was refreshed",
    refreshedUser.token.access,
    guestUser.token.access,
  );
  TestValidator.notEquals(
    "refresh token was refreshed",
    refreshedUser.token.refresh,
    guestUser.token.refresh,
  );

  // Step 6: Validate token structure and format
  const accessTokenParts = refreshedUser.token.access.split(".");
  TestValidator.equals(
    "access token has JWT format",
    accessTokenParts.length,
    3,
  );

  const refreshTokenParts = refreshedUser.token.refresh.split(".");
  TestValidator.equals(
    "refresh token has JWT format",
    refreshTokenParts.length,
    3,
  );

  // Step 7: Verify refreshed tokens have proper expiration timing
  const newExpiryTime = new Date(refreshedUser.token.expired_at).getTime();
  const oldExpiryTime = new Date(guestUser.token.expired_at).getTime();
  TestValidator.predicate(
    "new access token expires later than old one",
    newExpiryTime > oldExpiryTime,
  );

  const newRefreshExpiryTime = new Date(
    refreshedUser.token.refreshable_until,
  ).getTime();
  const oldRefreshExpiryTime = new Date(
    guestUser.token.refreshable_until,
  ).getTime();
  TestValidator.predicate(
    "new refresh token expires later than old one",
    newRefreshExpiryTime > oldRefreshExpiryTime,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconPoliticalDiscussionGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionGuestUser";

export async function test_api_guest_user_consecutive_token_refreshes(
  connection: api.IConnection,
) {
  // Step 1: Create guest user account to obtain initial refresh token
  const initialUser = await api.functional.auth.guestUser.join(connection, {
    body: {
      display_name: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      bio: RandomGenerator.paragraph(),
      avatar_url: typia.random<string & tags.Format<"uri">>(),
    } satisfies IEconPoliticalDiscussionGuestUser.ICreate,
  });
  typia.assert(initialUser);

  // Step 2: Store initial token information for comparison
  const initialAccessToken = initialUser.token.access;
  const initialRefreshToken = initialUser.token.refresh;
  const initialRefreshableUntil = initialUser.token.refreshable_until;
  const initialExpiredAt = initialUser.token.expired_at;

  TestValidator.equals(
    "initial user should have valid tokens",
    initialUser.token.access.length > 0,
    true,
  );
  TestValidator.equals(
    "initial user should have refresh token",
    initialUser.token.refresh.length > 0,
    true,
  );
  TestValidator.equals(
    "initial user should have expiration time",
    initialUser.token.expired_at.length > 0,
    true,
  );
  TestValidator.equals(
    "initial user should have refreshable until time",
    initialUser.token.refreshable_until.length > 0,
    true,
  );

  // Step 3: Perform first token refresh
  const firstRefresh =
    await api.functional.auth.guestUser.refresh.refreshToken(connection);
  typia.assert(firstRefresh);

  // Step 4: Validate first refresh results
  TestValidator.notEquals(
    "first refresh access token should be different",
    firstRefresh.token.access,
    initialAccessToken,
  );
  TestValidator.notEquals(
    "first refresh refresh token should be different",
    firstRefresh.token.refresh,
    initialRefreshToken,
  );
  TestValidator.equals(
    "user ID should remain consistent after first refresh",
    firstRefresh.id,
    initialUser.id,
  );
  TestValidator.equals(
    "display name should remain consistent after first refresh",
    firstRefresh.display_name,
    initialUser.display_name,
  );
  TestValidator.equals(
    "email should remain consistent after first refresh",
    firstRefresh.email,
    initialUser.email,
  );
  TestValidator.equals(
    "status should remain consistent after first refresh",
    firstRefresh.status,
    initialUser.status,
  );

  // Step 5: Verify token expiration times are extended
  const firstExpiredAt = new Date(firstRefresh.token.expired_at);
  const initialExpiredAtDate = new Date(initialExpiredAt);
  TestValidator.predicate(
    "first refresh should extend access token expiration",
    firstExpiredAt > initialExpiredAtDate,
  );

  const firstRefreshableUntil = new Date(firstRefresh.token.refreshable_until);
  const initialRefreshableUntilDate = new Date(initialRefreshableUntil);
  TestValidator.predicate(
    "first refresh should extend refresh token expiration",
    firstRefreshableUntil >= initialRefreshableUntilDate,
  );

  // Step 6: Perform second consecutive token refresh
  const secondRefresh =
    await api.functional.auth.guestUser.refresh.refreshToken(connection);
  typia.assert(secondRefresh);

  // Step 7: Validate second refresh results
  TestValidator.notEquals(
    "second refresh access token should be different from first",
    secondRefresh.token.access,
    firstRefresh.token.access,
  );
  TestValidator.notEquals(
    "second refresh refresh token should be different from first",
    secondRefresh.token.refresh,
    firstRefresh.token.refresh,
  );
  TestValidator.equals(
    "user identity should remain consistent after second refresh",
    secondRefresh.id,
    initialUser.id,
  );
  TestValidator.equals(
    "user profile should remain consistent after second refresh",
    secondRefresh.display_name,
    initialUser.display_name,
  );

  // Step 8: Verify second token expiration extension
  const secondExpiredAt = new Date(secondRefresh.token.expired_at);
  TestValidator.predicate(
    "second refresh should further extend access token expiration",
    secondExpiredAt > firstExpiredAt,
  );

  // Step 9: Perform third consecutive token refresh
  const thirdRefresh =
    await api.functional.auth.guestUser.refresh.refreshToken(connection);
  typia.assert(thirdRefresh);

  // Step 10: Validate third refresh results
  TestValidator.notEquals(
    "third refresh access token should be different from second",
    thirdRefresh.token.access,
    secondRefresh.token.access,
  );
  TestValidator.notEquals(
    "third refresh refresh token should be different from second",
    thirdRefresh.token.refresh,
    secondRefresh.token.refresh,
  );
  TestValidator.equals(
    "user session should remain consistent after third refresh",
    thirdRefresh.id,
    initialUser.id,
  );

  // Step 11: Verify final token expiration
  const thirdExpiredAt = new Date(thirdRefresh.token.expired_at);
  TestValidator.predicate(
    "third refresh should extend expiration even further",
    thirdExpiredAt > secondExpiredAt,
  );

  // Step 12: Test rapid consecutive refreshes (stress test)
  const rapidRefreshes = await Promise.all([
    api.functional.auth.guestUser.refresh.refreshToken(connection),
    api.functional.auth.guestUser.refresh.refreshToken(connection),
    api.functional.auth.guestUser.refresh.refreshToken(connection),
  ]);

  // Validate all rapid refresh results
  for (let i = 0; i < rapidRefreshes.length; i++) {
    const refresh = rapidRefreshes[i];
    typia.assert(refresh);

    TestValidator.equals(
      `rapid refresh ${i + 1} should maintain user identity`,
      refresh.id,
      initialUser.id,
    );
    TestValidator.equals(
      `rapid refresh ${i + 1} should maintain user profile`,
      refresh.display_name,
      initialUser.display_name,
    );
    TestValidator.equals(
      `rapid refresh ${i + 1} should have valid tokens`,
      refresh.token.access.length > 0,
      true,
    );
  }

  // Step 13: Verify that all rapid refresh tokens are unique
  const accessTokens = rapidRefreshes.map((r) => r.token.access);
  const refreshTokens = rapidRefreshes.map((r) => r.token.refresh);

  for (let i = 0; i < accessTokens.length; i++) {
    for (let j = i + 1; j < accessTokens.length; j++) {
      TestValidator.notEquals(
        `access token ${i + 1} should differ from ${j + 1}`,
        accessTokens[i],
        accessTokens[j],
      );
      TestValidator.notEquals(
        `refresh token ${i + 1} should differ from ${j + 1}`,
        refreshTokens[i],
        refreshTokens[j],
      );
    }
  }

  // Step 14: Final validation - ensure the session is still valid and functional
  const finalUser =
    await api.functional.auth.guestUser.refresh.refreshToken(connection);
  typia.assert(finalUser);

  TestValidator.equals(
    "final user identity should still match original",
    finalUser.id,
    initialUser.id,
  );
  TestValidator.equals(
    "final user should still be active",
    finalUser.status,
    "active",
  );
  TestValidator.equals(
    "final user should have valid updated tokens",
    finalUser.token.access.length > 0,
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconPoliticalDiscussionGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionGuestUser";

/**
 * Test token refresh with invalid or expired refresh token.
 *
 * This test validates that the system properly rejects invalid refresh tokens
 * and prevents unauthorized session extension. Ensures appropriate error
 * handling for tampered, expired, or non-existent refresh tokens.
 *
 * The test follows these steps:
 *
 * 1. Create a valid guest user to obtain proper authentication tokens
 * 2. Test refreshing with tampered/modified refresh token
 * 3. Test refreshing with expired-looking refresh token format
 * 4. Test refreshing with completely invalid token format
 * 5. Validate proper error responses for each invalid scenario
 */
export async function test_api_guest_user_invalid_refresh_token(
  connection: api.IConnection,
) {
  // Step 1: Create a valid guest user to get proper tokens for baseline
  const guestUser = await api.functional.auth.guestUser.join(connection, {
    body: {
      display_name: "Test Guest User",
      email: typia.random<string & tags.Format<"email">>(),
    } satisfies IEconPoliticalDiscussionGuestUser.ICreate,
  });
  typia.assert(guestUser);

  // Step 2: Test with tampered refresh token
  const tamperedToken = guestUser.token.refresh.slice(0, -5) + "XXXXX";
  const tamperedConn: api.IConnection = {
    ...connection,
    headers: { Authorization: `Bearer ${tamperedToken}` },
  };

  await TestValidator.error(
    "should reject tampered refresh token",
    async () => {
      await api.functional.auth.guestUser.refresh.refreshToken(tamperedConn);
    },
  );

  // Step 3: Test with completely invalid token format
  const invalidToken = "invalid-refresh-token-format";
  const invalidConn: api.IConnection = {
    ...connection,
    headers: { Authorization: `Bearer ${invalidToken}` },
  };

  await TestValidator.error(
    "should reject invalid refresh token format",
    async () => {
      await api.functional.auth.guestUser.refresh.refreshToken(invalidConn);
    },
  );

  // Step 4: Test with random string that doesn't look like a token
  const randomString = RandomGenerator.alphabets(50);
  const randomConn: api.IConnection = {
    ...connection,
    headers: { Authorization: `Bearer ${randomString}` },
  };

  await TestValidator.error(
    "should reject random string as refresh token",
    async () => {
      await api.functional.auth.guestUser.refresh.refreshToken(randomConn);
    },
  );

  // Step 5: Test with empty token
  const emptyConn: api.IConnection = {
    ...connection,
    headers: { Authorization: "Bearer " },
  };

  await TestValidator.error("should reject empty refresh token", async () => {
    await api.functional.auth.guestUser.refresh.refreshToken(emptyConn);
  });

  // Step 6: Test with JWT token that has valid format but refers to non-existent user
  const fakeJwtPayload = btoa(
    JSON.stringify({
      userId: "non-existent-user-12345",
      iat: Math.floor(Date.now() / 1000),
    }),
  );
  const fakeToken = `eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.${fakeJwtPayload}.fake-signature`;
  const fakeConn: api.IConnection = {
    ...connection,
    headers: { Authorization: `Bearer ${fakeToken}` },
  };

  await TestValidator.error(
    "should reject JWT token with non-existent user reference",
    async () => {
      await api.functional.auth.guestUser.refresh.refreshToken(fakeConn);
    },
  );

  // Step 7: Test with token missing required Bearer prefix
  const noBearerConn: api.IConnection = {
    ...connection,
    headers: { Authorization: guestUser.token.refresh },
  };

  await TestValidator.error(
    "should reject token without Bearer prefix",
    async () => {
      await api.functional.auth.guestUser.refresh.refreshToken(noBearerConn);
    },
  );
}

