import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconPoliticalDiscussionAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionAttachment";
import { IEconPoliticalDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionArticle";
import { RegisteredmemberPayload } from "../decorators/payload/RegisteredmemberPayload";

export async function getEconPoliticalDiscussionRegisteredMemberArticlesArticleIdAttachmentsAttachmentId(props: {
  registeredMember: RegisteredmemberPayload;
  articleId: string & tags.Format<"uuid">;
  attachmentId: string & tags.Format<"uuid">;
}): Promise<IEconPoliticalDiscussionAttachment> {
  // Fetch the attachment and verify it belongs to the specified article
  const attachment =
    await MyGlobal.prisma.econ_political_discussion_attachments.findFirst({
      where: {
        id: props.attachmentId,
        econ_political_discussion_article_id: props.articleId,
      },
      include: {
        article: {
          select: {
            id: true,
            title: true,
            category: true,
            status: true,
            created_at: true,
            updated_at: true,
            deleted_at: true,
          },
        },
      },
    });

  if (!attachment) {
    throw new HttpException(
      "Attachment not found or does not belong to the specified article",
      404,
    );
  }

  // Verify the article exists and is not deleted
  if (!attachment.article || attachment.article.deleted_at) {
    throw new HttpException("Article not found or has been deleted", 404);
  }

  // Check security scan status - only allow access to clean files or for administrative purposes
  const isOwner = attachment.uploader_name === props.registeredMember.id;

  if (attachment.security_scan_status === "quarantined") {
    throw new HttpException(
      "Attachment has been quarantined for security reasons",
      403,
    );
  }

  // Return the complete attachment metadata
  return {
    id: attachment.id,
    article: {
      id: attachment.article.id,
      title: attachment.article.title,
      category: attachment.article.category,
      status: attachment.article.status,
      created_at: toISOStringSafe(attachment.article.created_at),
      updated_at: toISOStringSafe(attachment.article.updated_at),
    },
    original_filename: attachment.original_filename,
    file_type: attachment.file_type,
    file_size: attachment.file_size,
    file_url: attachment.file_url,
    upload_date: toISOStringSafe(attachment.upload_date),
    uploader_name: attachment.uploader_name,
    security_scan_status: attachment.security_scan_status,
    moderation_status: attachment.moderation_status,
    is_public: attachment.is_public,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconPoliticalDiscussionAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionAttachment";
import { IPageIEconPoliticalDiscussionAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIEconPoliticalDiscussionAttachment";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IEconPoliticalDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionArticle";
import { IEconPoliticalDiscussionUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionUser";

export async function patchEconPoliticalDiscussionArticlesArticleIdAttachments(props: {
  articleId: string & tags.Format<"uuid">;
  body: IEconPoliticalDiscussionAttachment.IRequest;
}): Promise<IPageIEconPoliticalDiscussionAttachment.ISummary> {
  const { articleId } = props;
  const {
    page = 1,
    limit = 20,
    file_type,
    security_scan_status,
    moderation_status,
    is_public,
    order_by = "upload_date",
    order_direction = "desc",
  } = props.body;

  // Verify the article exists first
  const articleExists =
    await MyGlobal.prisma.econ_political_discussion_articles.findUnique({
      where: { id: articleId },
      select: { id: true },
    });

  if (!articleExists) {
    throw new HttpException("Article not found", 404);
  }

  // Build where conditions
  const whereConditions: Record<string, unknown> = {
    econ_political_discussion_article_id: articleId,
  };

  // Apply filters if provided
  if (file_type) {
    whereConditions.file_type = file_type;
  }

  if (security_scan_status) {
    whereConditions.security_scan_status =
      security_scan_status satisfies string as string;
  }

  if (moderation_status) {
    whereConditions.moderation_status =
      moderation_status satisfies string as string;
  }

  if (is_public !== undefined && is_public !== null) {
    whereConditions.is_public = is_public;
  }

  // Calculate pagination
  const pageNum = Number(page);
  const limitNum = Number(limit);
  const skip = (pageNum - 1) * limitNum;

  // Build orderBy clause - validate against actual database fields
  const validOrderFields = [
    "upload_date",
    "file_size",
    "file_type",
    "original_filename",
  ];
  const orderField = validOrderFields.includes(order_by)
    ? order_by
    : "upload_date";
  const orderBy: Record<string, "asc" | "desc"> = {};
  orderBy[orderField] = order_direction;

  // Execute queries in parallel
  const [attachments, total] = await Promise.all([
    MyGlobal.prisma.econ_political_discussion_attachments.findMany({
      where: whereConditions,
      skip,
      take: limitNum,
      orderBy,
    }),
    MyGlobal.prisma.econ_political_discussion_attachments.count({
      where: whereConditions,
    }),
  ]);

  // Get article data separately since relationship include is not supported
  const article =
    await MyGlobal.prisma.econ_political_discussion_articles.findUnique({
      where: { id: articleId },
      select: {
        id: true,
        title: true,
        category: true,
        status: true,
        created_at: true,
        updated_at: true,
      },
    });

  // Transform to DTO format
  const transformedAttachments = attachments.map((attachment) => ({
    id: attachment.id,
    original_filename: attachment.original_filename,
    file_type: attachment.file_type,
    file_size: attachment.file_size,
    upload_date: toISOStringSafe(attachment.upload_date),
    security_scan_status: attachment.security_scan_status satisfies string as
      | "clean"
      | "flagged"
      | "quarantined"
      | "pending"
      | "failed",
    moderation_status: attachment.moderation_status satisfies string as
      | "approved"
      | "rejected"
      | "pending",
    is_public: attachment.is_public,
    uploader: {
      id: v4() as string & tags.Format<"uuid">,
      display_name: attachment.uploader_name,
      avatar_url: undefined,
      status: "active",
    },
    article: article
      ? {
          id: article.id,
          title: article.title,
          category: article.category,
          status: article.status,
          created_at: toISOStringSafe(article.created_at),
          updated_at: toISOStringSafe(article.updated_at),
        }
      : {
          id: articleId,
          title: "",
          category: "",
          status: "draft",
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        },
  }));

  // Calculate pagination metadata
  const totalPages = Math.ceil(total / limitNum);

  return {
    data: transformedAttachments,
    pagination: {
      current: pageNum,
      limit: limitNum,
      records: total,
      pages: totalPages,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconPoliticalDiscussionGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionGuestUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { GuestuserPayload } from "../decorators/payload/GuestuserPayload";

export async function postAuthGuestUserJoin(props: {
  guestUser: GuestuserPayload;
  body: IEconPoliticalDiscussionGuestUser.ICreate;
}): Promise<IEconPoliticalDiscussionGuestUser.IAuthorized> {
  // Check for duplicate email
  const existingUser =
    await MyGlobal.prisma.econ_political_discussion_users.findFirst({
      where: {
        email: props.body.email,
        deleted_at: null,
      },
    });
  if (existingUser) {
    throw new HttpException("Email already registered", 409);
  }

  // Create the guest user record
  const user = await MyGlobal.prisma.econ_political_discussion_users.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      display_name: props.body.display_name,
      email: props.body.email,
      bio: props.body.bio ?? null,
      avatar_url: props.body.avatar_url ?? null,
      status: "active",
      created_at: toISOStringSafe(new Date()),
      updated_at: toISOStringSafe(new Date()),
      deleted_at: null,
    },
  });

  // Create session record
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  // Generate session ID for JWT payload (following the pattern from other auth systems)
  const sessionId = v4() as string & tags.Format<"uuid">;

  // Generate JWT tokens
  const token = {
    access: jwt.sign(
      {
        type: "guestuser",
        id: user.id,
        session_id: sessionId,
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "guestuser",
        id: user.id,
        session_id: sessionId,
        tokenType: "refresh",
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // Return the authorized user response
  return {
    id: user.id,
    display_name: user.display_name,
    email: user.email,
    bio: user.bio ?? undefined,
    avatar_url: user.avatar_url ?? undefined,
    status: user.status,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    deleted_at:
      user.deleted_at !== null ? toISOStringSafe(user.deleted_at) : undefined,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconPoliticalDiscussionRegisteredMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionRegisteredMember";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { RegisteredmemberPayload } from "../decorators/payload/RegisteredmemberPayload";

export async function postAuthRegisteredMemberRefresh(props: {
  registeredMember: RegisteredmemberPayload;
  body: IEconPoliticalDiscussionRegisteredMember.IRefresh;
}): Promise<IEconPoliticalDiscussionRegisteredMember.IAuthorized> {
  // Step 1: Verify and decode the refresh token
  let decoded: {
    id: string;
    session_id: string;
    type: "registeredmember";
  };
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as {
      id: string;
      session_id: string;
      type: "registeredmember";
    };
  } catch (error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  // Step 2: Validate token type matches expected actor type
  if (decoded.type !== "registeredmember") {
    throw new HttpException("Invalid token type", 403);
  }

  // Step 3: Validate that the session_id matches current session
  if (decoded.session_id !== props.registeredMember.session_id) {
    throw new HttpException("Session mismatch", 403);
  }

  // Step 4: Validate user account still exists and is active
  const user = await MyGlobal.prisma.econ_political_discussion_users.findFirst({
    where: {
      id: decoded.id,
      deleted_at: null,
      status: "active",
    },
  });

  if (!user) {
    throw new HttpException("Account not found or deactivated", 403);
  }

  // Step 5: Generate new tokens with same session_id for continuity
  const accessExpires: Date = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires: Date = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  const accessToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: new Date().toISOString(),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: new Date().toISOString(),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  // Step 6: Return user profile with new tokens
  return {
    id: user.id,
    display_name: user.display_name,
    email: user.email,
    bio: user.bio ?? undefined,
    avatar_url: user.avatar_url ?? undefined,
    status: user.status,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    deleted_at:
      user.deleted_at !== null ? toISOStringSafe(user.deleted_at) : undefined,
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: toISOStringSafe(accessExpires),
      refreshable_until: toISOStringSafe(refreshExpires),
    },
  };
}

