import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconPoliticalDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionArticle";
import { IEconPoliticalDiscussionUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionUser";
import { IEconPoliticalDiscussionAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionAttachment";

export async function deleteEconPoliticalDiscussionArticlesArticleId(props: {
  articleId: string & tags.Format<"uuid">;
}): Promise<IEconPoliticalDiscussionArticle> {
  // Find the article to be deleted
  const article =
    await MyGlobal.prisma.econ_political_discussion_articles.findUnique({
      where: { id: props.articleId },
    });

  if (!article) {
    throw new HttpException("Article not found", 404);
  }

  // Perform cascade deletion of all associated attachments
  await MyGlobal.prisma.econ_political_discussion_attachments.deleteMany({
    where: { econ_political_discussion_article_id: props.articleId },
  });

  // Perform soft delete by setting deleted_at timestamp
  const deletedArticle =
    await MyGlobal.prisma.econ_political_discussion_articles.update({
      where: { id: props.articleId },
      data: {
        deleted_at: new Date(),
      },
    });

  // Fetch the user data separately
  const user = await MyGlobal.prisma.econ_political_discussion_users.findUnique(
    {
      where: { id: deletedArticle.econ_political_discussion_user_id },
      select: {
        id: true,
        display_name: true,
        avatar_url: true,
        status: true,
      },
    },
  );

  // Fetch attachments (empty since we deleted them)
  const attachments: any[] = [];

  // Return the deleted article with proper formatting
  return {
    id: deletedArticle.id,
    title: deletedArticle.title,
    content: deletedArticle.content,
    category: deletedArticle.category,
    status: deletedArticle.status,
    econ_political_discussion_user_id:
      deletedArticle.econ_political_discussion_user_id,
    author: {
      id: user!.id,
      display_name: user!.display_name,
      avatar_url: user!.avatar_url ?? undefined,
      status: user!.status,
    },
    attachments: attachments.map((attachment: any) => ({
      id: attachment.id,
      article: {
        id: deletedArticle.id,
        title: deletedArticle.title,
        category: deletedArticle.category,
        status: deletedArticle.status,
        created_at: toISOStringSafe(deletedArticle.created_at),
        updated_at: toISOStringSafe(deletedArticle.updated_at),
      },
      original_filename: attachment.original_filename,
      file_type: attachment.file_type,
      file_size: attachment.file_size,
      file_url: attachment.file_url,
      upload_date: toISOStringSafe(attachment.upload_date),
      uploader_name: attachment.uploader_name,
      security_scan_status: attachment.security_scan_status,
      moderation_status: attachment.moderation_status,
      is_public: attachment.is_public,
    })),
    created_at: toISOStringSafe(deletedArticle.created_at),
    updated_at: toISOStringSafe(deletedArticle.updated_at),
    deleted_at: deletedArticle.deleted_at
      ? toISOStringSafe(deletedArticle.deleted_at)
      : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconPoliticalDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionArticle";
import { IEconPoliticalDiscussionAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionAttachment";
import { IEconPoliticalDiscussionUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionUser";

export async function postEconPoliticalDiscussionArticles(props: {
  body: IEconPoliticalDiscussionArticle.ICreate;
}): Promise<IEconPoliticalDiscussionArticle> {
  const { body } = props;

  // Validate that the referenced author exists
  const author =
    await MyGlobal.prisma.econ_political_discussion_users.findUnique({
      where: { id: body.econ_political_discussion_user_id },
    });

  if (!author) {
    throw new HttpException("Author not found", 404);
  }

  // Create the article and optionally handle attachments in a transaction
  const result = await MyGlobal.prisma.$transaction(async (tx) => {
    // Generate UUID for the new article
    const articleId = v4() as string & tags.Format<"uuid">;
    const now = new Date();

    // Create the main article record
    const article = await tx.econ_political_discussion_articles.create({
      data: {
        id: articleId,
        title: body.title,
        content: body.content,
        category: body.category,
        status: body.status ?? "published",
        econ_political_discussion_user_id:
          body.econ_political_discussion_user_id,
        created_at: now,
        updated_at: now,
      },
    });

    // Handle attachments if provided
    if (body.attachments && body.attachments.length > 0) {
      const attachments = await Promise.all(
        body.attachments.map((attachment) =>
          tx.econ_political_discussion_attachments.create({
            data: {
              id: v4() as string & tags.Format<"uuid">,
              econ_political_discussion_article_id: articleId,
              original_filename: attachment.original_filename,
              file_type: attachment.file_type,
              file_size: attachment.file_size,
              file_url: attachment.file_url,
              upload_date: now,
              uploader_name: attachment.uploader_name,
              security_scan_status: "pending",
              moderation_status: "pending",
              is_public: true,
            },
          }),
        ),
      );

      return {
        article,
        attachments,
      };
    }

    return {
      article,
      attachments: [],
    };
  });

  // Construct the response with author information
  const response: IEconPoliticalDiscussionArticle = {
    id: result.article.id,
    title: result.article.title,
    content: result.article.content,
    category: result.article.category,
    status: result.article.status,
    econ_political_discussion_user_id:
      result.article.econ_political_discussion_user_id,
    author: {
      id: author.id,
      display_name: author.display_name,
      avatar_url: author.avatar_url,
      status: author.status,
    },
    attachments: result.attachments.map((attachment) => ({
      id: attachment.id,
      article: {
        id: result.article.id,
        title: result.article.title,
        category: result.article.category,
        status: result.article.status,
        created_at: toISOStringSafe(result.article.created_at),
        updated_at: toISOStringSafe(result.article.updated_at),
      },
      original_filename: attachment.original_filename,
      file_type: attachment.file_type,
      file_size: attachment.file_size,
      file_url: attachment.file_url,
      upload_date: toISOStringSafe(attachment.upload_date),
      uploader_name: attachment.uploader_name,
      security_scan_status: attachment.security_scan_status,
      moderation_status: attachment.moderation_status,
      is_public: attachment.is_public,
    })),
    created_at: toISOStringSafe(result.article.created_at),
    updated_at: toISOStringSafe(result.article.updated_at),
    deleted_at: result.article.deleted_at
      ? toISOStringSafe(result.article.deleted_at)
      : null,
  };

  return response;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconPoliticalDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionArticle";
import { IEconPoliticalDiscussionAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionAttachment";
import { IEconPoliticalDiscussionUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionUser";
import { RegisteredmemberPayload } from "../decorators/payload/RegisteredmemberPayload";

export async function postEconPoliticalDiscussionRegisteredMemberArticles(props: {
  registeredMember: RegisteredmemberPayload;
  body: IEconPoliticalDiscussionArticle.ICreate;
}): Promise<IEconPoliticalDiscussionArticle> {
  // Generate UUID for new article
  const articleId = v4() as string & tags.Format<"uuid">;

  // Create article in transaction with attachments
  const result = await MyGlobal.prisma.$transaction(async (tx) => {
    // Create article
    const article = await tx.econ_political_discussion_articles.create({
      data: {
        id: articleId,
        title: props.body.title,
        content: props.body.content,
        category: props.body.category,
        status: props.body.status ?? "published",
        econ_political_discussion_user_id:
          props.body.econ_political_discussion_user_id,
        created_at: toISOStringSafe(new Date()),
        updated_at: toISOStringSafe(new Date()),
      },
    });

    // Create attachments if provided
    let attachments: any[] = [];
    if (props.body.attachments && props.body.attachments.length > 0) {
      const attachmentIds = props.body.attachments.map(
        () => v4() as string & tags.Format<"uuid">,
      );

      await tx.econ_political_discussion_attachments.createMany({
        data: props.body.attachments.map((attachment, index) => ({
          id: attachmentIds[index],
          econ_political_discussion_article_id: articleId,
          original_filename: attachment.original_filename,
          file_type: attachment.file_type,
          file_size: attachment.file_size,
          file_url: attachment.file_url,
          upload_date: toISOStringSafe(new Date()),
          uploader_name: attachment.uploader_name,
          security_scan_status: "pending",
          moderation_status: "pending",
          is_public: true,
        })),
      });

      // Fetch created attachments
      attachments = await tx.econ_political_discussion_attachments.findMany({
        where: { econ_political_discussion_article_id: articleId },
      });
    }

    // Fetch article with author info
    const articleWithAuthor =
      await tx.econ_political_discussion_articles.findUnique({
        where: { id: articleId },
        include: {
          econ_political_discussion_attachments: {
            select: {
              id: true,
              original_filename: true,
              file_type: true,
              file_size: true,
              file_url: true,
              upload_date: true,
              uploader_name: true,
              security_scan_status: true,
              moderation_status: true,
              is_public: true,
            },
          },
        },
      });

    // Fetch author separately
    const author = await tx.econ_political_discussion_users.findUnique({
      where: { id: props.body.econ_political_discussion_user_id },
      select: {
        id: true,
        display_name: true,
        avatar_url: true,
        status: true,
      },
    });

    if (!author) {
      throw new HttpException("Author not found", 404);
    }

    return {
      article: articleWithAuthor,
      attachments,
      author,
    };
  });

  if (!result.article) {
    throw new HttpException("Article creation failed", 500);
  }

  // Transform to API response format
  return {
    id: result.article.id,
    title: result.article.title,
    content: result.article.content,
    category: result.article.category,
    status: result.article.status,
    econ_political_discussion_user_id:
      result.article.econ_political_discussion_user_id,
    author: {
      id: result.author.id,
      display_name: result.author.display_name,
      avatar_url: result.author.avatar_url,
      status: result.author.status,
    },
    attachments: result.attachments.map((attachment) => ({
      id: attachment.id,
      article: {
        id: result.article!.id,
        title: result.article!.title,
        category: result.article!.category,
        status: result.article!.status,
        created_at: toISOStringSafe(result.article!.created_at),
        updated_at: toISOStringSafe(result.article!.updated_at),
      },
      original_filename: attachment.original_filename,
      file_type: attachment.file_type,
      file_size: attachment.file_size,
      file_url: attachment.file_url,
      upload_date: attachment.upload_date,
      uploader_name: attachment.uploader_name,
      security_scan_status: attachment.security_scan_status,
      moderation_status: attachment.moderation_status,
      is_public: attachment.is_public,
    })),
    created_at: toISOStringSafe(result.article.created_at),
    updated_at: toISOStringSafe(result.article.updated_at),
    deleted_at: result.article.deleted_at
      ? toISOStringSafe(result.article.deleted_at)
      : null,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconPoliticalDiscussionContentModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionContentModerator";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { ContentmoderatorPayload } from "../decorators/payload/ContentmoderatorPayload";

export async function postAuthContentModeratorLogin(props: {
  contentModerator: ContentmoderatorPayload;
  body: IEconPoliticalDiscussionContentModerator.ILogin;
}): Promise<IEconPoliticalDiscussionContentModerator.IAuthorized> {
  // Find content moderator user by email
  const user = await MyGlobal.prisma.econ_political_discussion_users.findFirst({
    where: {
      email: props.body.email,
      deleted_at: null,
    },
  });

  if (!user) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Verify user is active content moderator
  if (user.status !== "active") {
    throw new HttpException(
      "Account is not active for content moderation",
      403,
    );
  }

  // Generate session ID for token payload
  const sessionId = v4() as string & tags.Format<"uuid">;

  // Generate JWT tokens without session storage (token-based auth)
  const now = new Date();
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000); // 1 hour
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days

  const token = {
    access: jwt.sign(
      {
        type: "content_moderator",
        id: user.id,
        session_id: sessionId,
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "content_moderator",
        id: user.id,
        session_id: sessionId,
        tokenType: "refresh",
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  } satisfies IAuthorizationToken;

  // Return authorized response
  return {
    id: user.id,
    display_name: user.display_name,
    email: user.email,
    bio: user.bio ?? undefined,
    avatar_url: user.avatar_url ?? undefined,
    status: user.status,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    deleted_at: user.deleted_at ? toISOStringSafe(user.deleted_at) : undefined,
    token,
  };
}

