import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconPoliticalDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionArticle";
import { IPageIEconPoliticalDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIEconPoliticalDiscussionArticle";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { RegisteredmemberPayload } from "../decorators/payload/RegisteredmemberPayload";

export async function patchUsersUserIdArticles(props: {
  registeredMember: RegisteredmemberPayload;
  userId: string & tags.Format<"uuid">;
  body: IEconPoliticalDiscussionArticle.IRequest;
}): Promise<IPageIEconPoliticalDiscussionArticle.ISummary> {
  const { registeredMember, userId, body } = props;

  const page = body.page ?? 1;
  const limit = Math.min(body.limit ?? 20, 50);
  const skip = (page - 1) * limit;

  // Build dynamic where conditions
  const whereConditions: Prisma.econ_political_discussion_articlesWhereInput = {
    // Only return articles by the specified user
    author: {
      id: userId,
    },
    // Only active articles (not deleted)
    deleted_at: null,
  };

  // Apply search filter if provided
  if (body.search) {
    whereConditions.OR = [
      { title: { contains: body.search, mode: "insensitive" } },
      { content: { contains: body.search, mode: "insensitive" } },
    ];
  }

  // Apply category filter if provided
  if (body.category) {
    whereConditions.category = body.category;
  }

  // Apply status filter if provided
  if (body.status) {
    whereConditions.status = body.status;
  }

  // Determine sorting
  const orderBy: Prisma.econ_political_discussion_articlesOrderByWithRelationInput =
    {};
  const sortField = body.order_by ?? "created_at";
  const sortDirection = body.order_direction ?? "desc";

  orderBy[sortField] = sortDirection;

  // Execute queries in parallel for efficiency
  const [data, total] = await Promise.all([
    MyGlobal.prisma.econ_political_discussion_articles.findMany({
      where: whereConditions,
      skip,
      take: limit,
      orderBy,
      select: {
        id: true,
        title: true,
        category: true,
        status: true,
        created_at: true,
        updated_at: true,
      },
    }),
    MyGlobal.prisma.econ_political_discussion_articles.count({
      where: whereConditions,
    }),
  ]);

  // Transform data to match ISummary interface
  const transformedData: IEconPoliticalDiscussionArticle.ISummary[] = data.map(
    (article) => ({
      id: article.id,
      title: article.title,
      category: article.category,
      status: article.status,
      created_at: toISOStringSafe(article.created_at),
      updated_at: toISOStringSafe(article.updated_at),
    }),
  );

  return {
    data: transformedData,
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconPoliticalDiscussionRegisteredMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconPoliticalDiscussionRegisteredMember";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { RegisteredmemberPayload } from "../decorators/payload/RegisteredmemberPayload";

export async function postAuthRegisteredMemberJoin(props: {
  registeredMember: RegisteredmemberPayload;
  body: IEconPoliticalDiscussionRegisteredMember.ICreate;
}): Promise<IEconPoliticalDiscussionRegisteredMember.IAuthorized> {
  // Step 1: Validate unique email constraint
  const existingUser =
    await MyGlobal.prisma.econ_political_discussion_users.findFirst({
      where: {
        email: props.body.email,
        deleted_at: null,
      },
    });

  if (existingUser) {
    throw new HttpException("Email already registered", 409);
  }

  // Step 2: Create user actor record with required fields
  const user = await MyGlobal.prisma.econ_political_discussion_users.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      display_name: props.body.display_name,
      email: props.body.email,
      bio: props.body.bio,
      avatar_url: props.body.avatar_url,
      status: "active",
      created_at: toISOStringSafe(new Date()),
      updated_at: toISOStringSafe(new Date()),
    },
  });

  // Step 3: Generate JWT tokens without session record (since sessions table doesn't exist)
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000); // 1 hour
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days

  const token = {
    access: jwt.sign(
      {
        type: "registeredmember",
        id: user.id,
        session_id: v4() as string & tags.Format<"uuid">, // Generate temporary session ID
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "registeredmember",
        id: user.id,
        session_id: v4() as string & tags.Format<"uuid">,
        tokenType: "refresh",
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // Step 4: Return user profile with authentication tokens
  return {
    id: user.id,
    display_name: user.display_name,
    email: user.email,
    bio: user.bio ?? undefined,
    avatar_url: user.avatar_url ?? undefined,
    status: user.status,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    deleted_at: user.deleted_at ? toISOStringSafe(user.deleted_at) : undefined,
    token,
  };
}

